class OrderRich {
    private String status = "PENDING";

    void ship() {
        if (!status.equals("PENDING")) {
            throw new IllegalStateException("Nie mozna wyslac zamowienia w stanie: " + status);
        }
        status = "SHIPPED";
    }

    void cancel() {
        if (status.equals("SHIPPED")) {
            throw new IllegalStateException("Nie mozna anulowac juz wyslanego zamowienia");
        }
        status = "CANCELLED";
    }

    String getStatus() { return status; } // odczyt bez ograniczen - tylko zapis jest chroniony
}

// ZLE: regula rozproszona - kazda metoda Service musi pamietac o jej powtorzeniu
class OrderServiceAnemic {
    void cancelOrder(OrderAnemic order) {
        if (order.getStatus().equals("SHIPPED")) {
            throw new IllegalStateException("Nie mozna anulowac wyslanego zamowienia");
        }
        order.setStatus("CANCELLED");
    }

    void cancelOrderViaAdminPanel(OrderAnemic order) {
        // ktos zapomnial powtorzyc walidacje w tej nowej metodzie!
        order.setStatus("CANCELLED"); // <- reguła ZLAMANA, brak sprawdzenia
    }
}

// DOBRZE: kazdy Service korzysta z tej samej, chronionej metody encji
class OrderServiceRich {
    void cancelOrder(OrderRich order) {
        order.cancel(); // regula sprawdzana WEWNATRZ encji, nie da sie jej pominac
    }

    void cancelOrderViaAdminPanel(OrderRich order) {
        order.cancel(); // DOKLADNIE ta sama, bezpieczna sciezka
    }
}
